<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/bootstrap.php';
use AcePortal\\Auth;
$u=Auth::requireRoles(['admin']);$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();try{$name=trim((string)($_POST['full_name']??''));$email=mb_strtolower(trim((string)($_POST['email']??'')));$pass=(string)($_POST['password']??'');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Enter a name and valid email.');if(strlen($pass)<12)throw new RuntimeException('Password must be at least 12 characters.');$q=db()->prepare("INSERT INTO users(role,full_name,email,password_hash,created_by) VALUES('staff',:n,:e,:p,:a)");$q->execute(['n'=>$name,'e'=>$email,'p'=>password_hash($pass,PASSWORD_DEFAULT),'a'=>$u['id']]);$id=(int)db()->lastInsertId();audit('create','user',$id,'Created staff account');flash('success','Staff account created. Share temporary password securely.');redirect('/agency/staff.php');}catch(Throwable $x){$error=$x instanceof PDOException&&(string)$x->getCode()==='23000'?'Email already exists.':$x->getMessage();}}
$flash=getFlash();$staff=db()->query("SELECT id,full_name,email,is_active,created_at FROM users WHERE role='staff' ORDER BY id DESC")->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Staff Accounts</title><link rel="stylesheet" href="/assets/app.css"></head><body><header class="topbar"><div><strong>ACE Insurance</strong><span>Agency Portal</span></div><div><?=e($u['full_name'])?> · Admin <a class="btn light small-btn" href="/logout.php">Logout</a></div></header><div class="layout"><aside class="sidebar"><a href="/agency/index.php">Dashboard</a><a href="/agency/crud.php?entity=insureds">Insureds</a><a href="/agency/crud.php?entity=vehicles">Vehicles</a><a href="/agency/crud.php?entity=policies">Policies</a><a href="/agency/crud.php?entity=drivers">Drivers</a><a class="selected" href="/agency/staff.php">Staff Accounts</a><a href="/agency/audit-logs.php">Activity Logs</a></aside><main class="main"><div class="page-title"><div><h1>Staff Accounts</h1><p class="muted">Admin-only staff creation.</p></div></div><?php if($flash):?><div class="alert success"><?=e($flash['message'])?></div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><div class="panel"><h2>Create Staff</h2><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?=e(csrfToken())?>"><label>Full Name<input name="full_name" required></label><label>Email<input type="email" name="email" required></label><label>Temporary Password<input type="password" name="password" minlength="12" required></label><div class="form-actions"><button class="btn primary">Create Staff</button></div></form></div><div class="panel"><h2>Staff Members</h2><div class="table-wrap"><table><thead><tr><th>ID</th><th>Name</th><th>Email</th><th>Status</th><th>Created</th></tr></thead><tbody><?php foreach($staff as $s):?><tr><td><?=$s['id']?></td><td><?=e($s['full_name'])?></td><td><?=e($s['email'])?></td><td><?=$s['is_active']?'Active':'Disabled'?></td><td><?=e($s['created_at'])?></td></tr><?php endforeach;?></tbody></table></div></div></main></div></body></html>